pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // The admin is the deployer of setUp (address(this)).
        // We assume caller is NOT the admin to check the non-admin path.
        vm.assume(caller != address(this));
        // ensure newOwner is different from the current owner to detect a silent change
        vm.assume(newOwner != c.owner());

        address ownerBefore = c.owner();

        vm.prank(caller);
        c.setOwner(newOwner);

        address ownerAfter = c.owner();
        // In the correct contract, a non-admin call must leave owner unchanged.
        // In the mutant, owner changes to newOwner.
        assertEq(ownerAfter, ownerBefore, "Non-admin must not change owner");
    }
}

