pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);
        vm.assume(caller != address(this)); // setUp deployer is owner/admin; exclude it to test general rule

        // Record original owner
        address ownerBefore = c.owner();

        // Call setOwner as the fuzzed caller
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        // After the call, the rule: if setOwner succeeded, and the caller was not the deployer (ownerBefore),
        // the reference would have reverted. Since it didn't revert, the bug is triggered.
        // But we need a general rule for the REFERENCE: For any non-deployer caller, setOwner must revert.
        // We assert that success is false for all non-deployer callers.
        // In the buggy version, success can be true when caller is not deployer (e.g., caller == ownerBefore after setup step).
        // The reference satisfies: for any non-deployer, setOwner reverts -> success is false.
        assertTrue(!success || caller == ownerBefore);
    }
}

