import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address admin, address newOwner) public {
        vm.assume(admin != address(0));
        vm.deal(admin, 0);
        vm.prank(admin);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        // For a non-zero admin (the deployer), setOwner must succeed and return true in the reference;
        // the buggy version always reverts, so ok will be false when called by any address including the admin.
        assertTrue(ok);
    }
}

